import{_ as t,o,c as a,a3 as d}from"./chunks/framework.CchDE9cb.js";const p=JSON.parse(`{"title":"Configuration","description":"Every CapacityLens environment variable, grouped by what you're trying to configure rather than alphabetically.","frontmatter":{"title":"Configuration","description":"Every CapacityLens environment variable, grouped by what you're trying to configure rather than alphabetically."},"headers":[],"relativePath":"self-hosting/configuration.md","filePath":"self-hosting/configuration.md","lastUpdated":null}`),r={name:"self-hosting/configuration.md"};function i(n,e,s,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>CapacityLens is configured entirely through environment variables, read from <code>.env</code> by Docker Compose or set directly for a bare-metal run. <code>.env.example</code> in the repository is the complete, authoritative register with defaults — this page groups the variables that matter for a self-hosted install by what you&#39;re trying to do. Server variables (<code>CAPACITYLENS_*</code>, <code>SMALLSASS_ACCOUNT_*</code>) take effect on restart. Client variables (<code>VITE_CAPACITYLENS_*</code>) are baked into the web app at build time, so changing one needs a rebuild.</p><h2 id="sign-in-mode" tabindex="-1">Sign-in mode <a class="header-anchor" href="#sign-in-mode" aria-label="Permalink to &quot;Sign-in mode&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>What it does</th></tr></thead><tbody><tr><td><code>SMALLSASS_ACCOUNT_MODE</code></td><td><code>off</code>, <code>password</code> or <code>sso</code>. <code>off</code> creates no sign-in at all; production refuses to boot with it unset unless you explicitly opt in (see below).</td></tr><tr><td><code>SMALLSASS_ACCOUNT_DEPLOYMENT_PROFILE</code></td><td>An optional named policy: <code>self-hosted-password</code>, <code>self-hosted-mixed</code> or <code>self-hosted-sso-only</code>. Enforced at startup.</td></tr><tr><td><code>SMALLSASS_ACCOUNT_SECRET</code></td><td>The session-signing secret. Required for <code>password</code> or <code>sso</code> mode. Generate with <code>openssl rand -base64 48</code> — anything 32 characters or longer is fine; the install guide&#39;s command produces 48.</td></tr><tr><td><code>SMALLSASS_ACCOUNT_PUBLIC_URL</code></td><td>The exact browser-facing origin, for example <code>https://capacity.example.com</code>. Required for <code>password</code> or <code>sso</code> mode.</td></tr><tr><td><code>SMALLSASS_ACCOUNT_SETUP_TOKEN</code></td><td>The one-time secret the first owner enters to create the first account. Required unless open signup or the bootstrap-admin escape hatch is enabled.</td></tr><tr><td><code>SMALLSASS_ACCOUNT_ALLOW_OPEN_SIGNUP</code></td><td>Re-opens self-service sign-up. Closed by default — CapacityLens is invite-only unless you set this. Leave it unset in production.</td></tr><tr><td><code>CAPACITYLENS_ALLOW_OPEN_IN_PRODUCTION</code></td><td>Deliberately allows the auth-off (<code>off</code>) posture under production. Off by default; without it, a production instance with no sign-in refuses to start.</td></tr></tbody></table><h2 id="passwords-and-multi-factor-sign-in" tabindex="-1">Passwords and multi-factor sign-in <a class="header-anchor" href="#passwords-and-multi-factor-sign-in" aria-label="Permalink to &quot;Passwords and multi-factor sign-in&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>What it does</th></tr></thead><tbody><tr><td><code>SMALLSASS_ACCOUNT_REQUIRE_MFA</code></td><td>Set <code>1</code> to require every password-mode teammate to enroll multi-factor sign-in before they can see company data.</td></tr><tr><td><code>SMALLSASS_ACCOUNT_PASSWORD_BREACH_CHECK</code></td><td>On by default: new passwords are checked against known breaches. Set <code>off</code> only for an isolated deployment that accepts the production warning.</td></tr></tbody></table><h2 id="company-login" tabindex="-1">Company login <a class="header-anchor" href="#company-login" aria-label="Permalink to &quot;Company login&quot;">​</a></h2><p>Read <a href="/capacitylens/company-login/set-up-company-login">Set up company login</a> first. These variables configure the strict <a href="/capacitylens/reference/glossary">OIDC</a> provider CapacityLens supports.</p><table tabindex="0"><thead><tr><th>Variable</th><th>What it does</th></tr></thead><tbody><tr><td><code>SMALLSASS_ACCOUNT_OIDC_CLIENT_ID</code> / <code>SMALLSASS_ACCOUNT_OIDC_CLIENT_SECRET</code></td><td>The client credentials from your company login provider. Both required for <code>sso</code> mode.</td></tr><tr><td><code>SMALLSASS_ACCOUNT_OIDC_ISSUER</code></td><td>The exact issuer URL your provider reports. Required.</td></tr><tr><td><code>SMALLSASS_ACCOUNT_OIDC_DISCOVERY_URL</code></td><td>The provider&#39;s <code>.well-known/openid-configuration</code> URL. Required — the authorisation, token, JWKS and user-info endpoints all come from discovery, not from manual overrides.</td></tr><tr><td><code>SMALLSASS_ACCOUNT_OIDC_BOOTSTRAP_EMAILS</code></td><td>Comma-separated verified emails allowed to create the first company-login identity. Every identity after that needs a pre-authorised invitation instead.</td></tr><tr><td><code>SMALLSASS_ACCOUNT_OIDC_PROVIDER_ID</code></td><td>Optional id used in the sign-in route. Defaults to <code>sso</code>. Can&#39;t be a name CapacityLens already uses internally (<code>credential</code>, <code>generic-oauth</code>, <code>two-factor</code>, <code>google</code>, <code>microsoft</code>, <code>github</code>).</td></tr><tr><td><code>SMALLSASS_ACCOUNT_OIDC_LABEL</code></td><td>Optional button label. Defaults to &quot;Single sign-on&quot;.</td></tr><tr><td><code>SMALLSASS_ACCOUNT_OIDC_SCOPES</code></td><td>Space-separated scopes. Defaults to <code>openid profile email</code>, all of which are required.</td></tr><tr><td><code>SMALLSASS_ACCOUNT_SSO_MFA_ENFORCED</code></td><td>An attestation that your company login provider requires multi-factor sign-in for every admitted identity. Set it only after testing that policy.</td></tr></tbody></table><p>Once the first successful startup has happened, the provider id and issuer are locked together — changing either refuses startup, to protect existing sign-in records. See <a href="/capacitylens/company-login/move-to-single-sign-on">Move to single sign-on</a> for converting an existing password installation.</p><p>Google, Microsoft and GitHub sign-in buttons are available and experimental through <code>SMALLSASS_ACCOUNT_GOOGLE_CLIENT_ID</code>/<code>SMALLSASS_ACCOUNT_GOOGLE_CLIENT_SECRET</code> and the equivalent Microsoft and GitHub pairs (Microsoft also takes an optional <code>SMALLSASS_ACCOUNT_MICROSOFT_TENANT_ID</code>, defaulting to <code>common</code>). Each provider needs both its id and secret set, or it&#39;s off. Strict OIDC above is the supported, provider-neutral path.</p><h2 id="the-database-and-backups" tabindex="-1">The database and backups <a class="header-anchor" href="#the-database-and-backups" aria-label="Permalink to &quot;The database and backups&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>What it does</th></tr></thead><tbody><tr><td><code>CAPACITYLENS_DB</code></td><td>Path to the SQLite file. Docker Compose pins this to <code>/data/capacitylens.db</code> inside a named volume; only change it for a bare-metal run.</td></tr><tr><td><code>CAPACITYLENS_BACKUP_DIR</code></td><td>Directory for scheduled snapshots. On by default in Docker (<code>/backups</code>). Set it explicitly empty (<code>CAPACITYLENS_BACKUP_DIR=</code>) to turn scheduled backups off.</td></tr><tr><td><code>CAPACITYLENS_BACKUP_INTERVAL_MIN</code></td><td>Minutes between snapshots. Whole minutes, default 60; startup clamps over-maximum values to 35,000 with a warning.</td></tr><tr><td><code>CAPACITYLENS_BACKUP_KEEP</code></td><td>How many snapshots to retain. Default 48. Invalid and lower values use the safe default; over-maximum values clamp to 10,000 with a startup warning, so leave disk capacity for that many restore points.</td></tr><tr><td><code>CAPACITYLENS_AUDIT_FILE</code></td><td>Path to the audit log. Default <code>capacitylens-audit.jsonl</code> next to <code>CAPACITYLENS_DB</code>; Docker Compose pins it to <code>/data/capacitylens-audit.jsonl</code>. Only read when audit logging is on.</td></tr><tr><td><code>CAPACITYLENS_AUDIT_MAX_MB</code></td><td>Audit log rotation size cap in MB. Default 64 — once the file reaches this size it&#39;s rotated to <code>&lt;file&gt;.1</code> (replacing any previous <code>.1</code>), bounding disk use to roughly twice the cap.</td></tr></tbody></table><p>See <a href="/capacitylens/self-hosting/backups-and-restore">Backups and restore</a> for what these snapshots protect against and how to use them. Back up the rotated <code>&lt;file&gt;.1</code> audit file alongside the current one — a restore that only picks up the live file can miss recent audit history still sitting in the rotated generation.</p><h2 id="origin-cors-and-proxy-trust" tabindex="-1">Origin, CORS and proxy trust <a class="header-anchor" href="#origin-cors-and-proxy-trust" aria-label="Permalink to &quot;Origin, CORS and proxy trust&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>What it does</th></tr></thead><tbody><tr><td><code>CAPACITYLENS_CORS_ORIGIN</code></td><td>Comma-separated browser origins to allow, only needed if the web app and API are on different origins. Unset means fail-closed: no cross-origin API calls, which is correct for the packaged same-origin nginx setup.</td></tr><tr><td><code>CAPACITYLENS_HTTPS</code></td><td>Set <code>1</code> when the public origin is genuinely HTTPS, to enable a two-year HSTS header. Leave unset if your proxy already emits HSTS.</td></tr><tr><td><code>CAPACITYLENS_TRUST_PROXY_HEADERS</code></td><td>Trusts <code>X-Forwarded-For</code>/<code>X-Forwarded-Proto</code> from a non-loopback listener. Docker Compose sets this to <code>1</code> because its API only accepts connections from the packaged nginx. Loopback listeners (<code>127.0.0.1</code>, <code>localhost</code>, <code>::1</code>) trust their same-host proxy automatically without this flag.</td></tr></tbody></table><p>See <a href="/capacitylens/self-hosting/tls-and-networking">TLS and networking</a> for the full picture.</p><h2 id="companies-on-this-instance" tabindex="-1">Companies on this instance <a class="header-anchor" href="#companies-on-this-instance" aria-label="Permalink to &quot;Companies on this instance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>What it does</th></tr></thead><tbody><tr><td><code>CAPACITYLENS_MULTI_ACCOUNT</code></td><td>Off by default: one company per instance. Set <code>1</code> to allow more than one.</td></tr><tr><td><code>CAPACITYLENS_BOOTSTRAP_TOKEN</code></td><td>A shared secret for creating an additional company through the API when the caller isn&#39;t already an owner or admin of one. Only matters when <code>CAPACITYLENS_MULTI_ACCOUNT=1</code>.</td></tr><tr><td><code>CAPACITYLENS_SEED_DEMO</code></td><td>Seeds a two-company sample dataset on a never-initialised database. Only makes sense paired with <code>CAPACITYLENS_MULTI_ACCOUNT=1</code>; use it for a throwaway or demo instance, not a real one.</td></tr></tbody></table><h2 id="health-logging-and-rate-limiting" tabindex="-1">Health, logging and rate limiting <a class="header-anchor" href="#health-logging-and-rate-limiting" aria-label="Permalink to &quot;Health, logging and rate limiting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>What it does</th></tr></thead><tbody><tr><td><code>CAPACITYLENS_LOG</code></td><td>Set <code>1</code> for structured per-request JSON logs. Recommended for a real deployment.</td></tr><tr><td><code>CAPACITYLENS_HEALTH_DEEP</code></td><td>Set <code>1</code> to make <code>/api/health</code> run a readiness query and report audit, backup and certificate status. Compose sets this by default.</td></tr><tr><td><code>CAPACITYLENS_RATE_LIMIT</code></td><td>Requests per minute per IP across rate-limited routes. Production refuses to start with it unset or zero.</td></tr><tr><td><code>CAPACITYLENS_AUDIT_STDOUT</code></td><td>Set <code>1</code> to also write each audit record to stdout as JSON, for a container log collector. Compose defaults this on.</td></tr><tr><td><code>CAPACITYLENS_SECURITY_LOG_FORWARDING</code></td><td>An attestation that you&#39;re forwarding audit and security events to a separate collector. Doesn&#39;t create the collector itself.</td></tr></tbody></table><p>See <a href="/capacitylens/self-hosting/monitoring">Monitoring and health checks</a> for what to do with these.</p><h2 id="what-the-web-app-is-built-with" tabindex="-1">What the web app is built with <a class="header-anchor" href="#what-the-web-app-is-built-with" aria-label="Permalink to &quot;What the web app is built with&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>What it does</th></tr></thead><tbody><tr><td><code>VITE_CAPACITYLENS_API</code></td><td>The API origin the built app talks to. Leave empty for the normal same-origin build (the app calls a relative <code>/api</code>, which nginx proxies). Only set this to point the app at a different origin.</td></tr><tr><td><code>VITE_CAPACITYLENS_DEMO</code></td><td>Set <code>1</code> to build the in-memory demo instead of the real app. Wins over <code>VITE_CAPACITYLENS_API</code> if both are set.</td></tr><tr><td><code>VITE_CAPACITYLENS_BUILD_SHA</code></td><td>Optional build identifier shown in Settings, typically the git commit.</td></tr><tr><td><code>VITE_CAPACITYLENS_FEEDBACK_MAILTO</code></td><td>Optional email address for the in-app feedback link. Leave empty to hide the link.</td></tr></tbody></table><p>Any of these needs a rebuild (<code>docker compose build web</code>, or <code>build web-client</code> for the client-only image) to take effect — setting them in a running container&#39;s environment does nothing.</p><h2 id="older-variable-names" tabindex="-1">Older variable names <a class="header-anchor" href="#older-variable-names" aria-label="Permalink to &quot;Older variable names&quot;">​</a></h2><p>Earlier releases used <code>CAPACITYLENS_AUTH</code>, <code>BETTER_AUTH_*</code>, <code>CAPACITYLENS_SSO_*</code> and named-social-provider variables with different names than the <code>SMALLSASS_ACCOUNT_*</code> ones above. Those older names still work as aliases, but they&#39;re deprecated: CapacityLens warns once, without logging the value, when it sees only the old name, and refuses to start if an old and a new name are both set but disagree. Move to the <code>SMALLSASS_ACCOUNT_*</code> names above when you next touch your configuration — the aliases won&#39;t be removed until at least two stable minor releases and 90 days have passed since the canonical names first shipped, so there&#39;s no rush, but new deployments should use the current names from the start.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="/capacitylens/self-hosting/install-with-docker">Install with Docker</a> if you haven&#39;t set these yet.</li><li><a href="/capacitylens/self-hosting/tls-and-networking">TLS and networking</a> for the proxy and cookie requirements these variables assume.</li></ul>',29)])])}const S=t(r,[["render",i]]);export{p as __pageData,S as default};
